// [S4] Derives "am I the Family Head?" from the family dashboard summary,
// so screens outside the dashboard (booking, my-doctor) can gate actions.
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

final isFamilyHeadProvider = FutureProvider.autoDispose<bool>((ref) async {
  final dashboard = await ref.watch(familyDashboardProvider.future);
  return dashboard.isHead;
});
